-- Generated by Export-SuperUser.ps1; execute the entire generated file in one session.
-- Contains a password hash. Do not commit or share publicly.
-- In SSMS select the target database and edit @ExpectedDatabase above.
-- First run with @Apply = 0; review the result, then rerun with @Apply = 1.
-- Take a production backup before the committed run. No schema migrations are applied.
DECLARE @Apply bit = 0;
SET NOCOUNT ON;
SET XACT_ABORT ON;

IF @@TRANCOUNT <> 0
    THROW 51000, 'Run in a session without an existing transaction.', 1;
IF DB_NAME() <> @ExpectedDatabase OR @ExpectedDatabase = N'PRODUKCIJA'
    THROW 51000, 'Select the target database and replace PRODUKCIJA with its exact name.', 1;
IF DB_NAME() = @SourceDatabase
    THROW 51000, 'Target has the source database name. Review the target before removing this guard.', 1;
IF ISJSON(@Payload) <> 1
    THROW 51000, 'Invalid export payload.', 1;

DECLARE @Users TABLE (
    Id nvarchar(450), UserName nvarchar(256), NormalizedUserName nvarchar(256),
    Email nvarchar(256), NormalizedEmail nvarchar(256), EmailConfirmed bit,
    PasswordHash nvarchar(max), PhoneNumber nvarchar(max), PhoneNumberConfirmed bit,
    TwoFactorEnabled bit, LockoutEnd datetimeoffset, LockoutEnabled bit, AccessFailedCount int
);
INSERT @Users SELECT * FROM OPENJSON(@Payload, '$.Users') WITH (
    Id nvarchar(450), UserName nvarchar(256), NormalizedUserName nvarchar(256),
    Email nvarchar(256), NormalizedEmail nvarchar(256), EmailConfirmed bit,
    PasswordHash nvarchar(max), PhoneNumber nvarchar(max), PhoneNumberConfirmed bit,
    TwoFactorEnabled bit, LockoutEnd datetimeoffset, LockoutEnabled bit, AccessFailedCount int
);
DECLARE @Roles TABLE (Id nvarchar(450) PRIMARY KEY, Name nvarchar(256), NormalizedName nvarchar(256));
INSERT @Roles SELECT * FROM OPENJSON(@Payload, '$.Roles') WITH (
    Id nvarchar(450), Name nvarchar(256), NormalizedName nvarchar(256));
DECLARE @UserClaims TABLE (ClaimType nvarchar(max), ClaimValue nvarchar(max));
INSERT @UserClaims SELECT DISTINCT * FROM OPENJSON(@Payload, '$.UserClaims') WITH (
    ClaimType nvarchar(max), ClaimValue nvarchar(max));
DECLARE @RoleClaims TABLE (RoleId nvarchar(450), ClaimType nvarchar(max), ClaimValue nvarchar(max));
INSERT @RoleClaims SELECT DISTINCT * FROM OPENJSON(@Payload, '$.RoleClaims') WITH (
    RoleId nvarchar(450), ClaimType nvarchar(max), ClaimValue nvarchar(max));

IF (SELECT COUNT(*) FROM @Users) <> 1 OR NOT EXISTS (SELECT 1 FROM @Users
    WHERE Id IS NOT NULL AND Email = N'admin@vranjic.local' AND NormalizedEmail = N'ADMIN@VRANJIC.LOCAL'
        AND UserName = N'admin@vranjic.local' AND NormalizedUserName = N'ADMIN@VRANJIC.LOCAL'
        AND EmailConfirmed = 1 AND NULLIF(PasswordHash, N'') IS NOT NULL AND TwoFactorEnabled = 0
        AND (LockoutEnabled = 0 OR LockoutEnd IS NULL OR LockoutEnd <= SYSDATETIMEOFFSET()))
    THROW 51000, 'Export must contain only the confirmed, unlocked admin@vranjic.local password account without 2FA.', 1;
IF NOT EXISTS (SELECT 1 FROM @Roles WHERE Name = N'SuperUser' AND NormalizedName = N'SUPERUSER')
    OR EXISTS (SELECT 1 FROM @Roles WHERE Name IS NULL OR NormalizedName IS NULL)
    OR EXISTS (SELECT NormalizedName FROM @Roles GROUP BY NormalizedName HAVING COUNT(*) > 1)
    OR EXISTS (SELECT 1 FROM @RoleClaims c WHERE NOT EXISTS (SELECT 1 FROM @Roles r WHERE r.Id = c.RoleId))
    THROW 51000, 'Invalid role export or missing SuperUser membership.', 1;

BEGIN TRY
    BEGIN TRANSACTION;
    -- Use existing destination IDs by normalized name. Never overwrite shared role definitions.
    DECLARE @RoleMap TABLE (SourceId nvarchar(450) PRIMARY KEY, TargetId nvarchar(450), IsNew bit);
    INSERT @RoleMap
    SELECT s.Id, COALESCE(t.Id, s.Id), CASE WHEN t.Id IS NULL THEN 1 ELSE 0 END
    FROM @Roles s LEFT JOIN dbo.AspNetRoles t WITH (UPDLOCK, HOLDLOCK) ON t.NormalizedName = s.NormalizedName;
    IF EXISTS (SELECT 1 FROM @Roles s JOIN @RoleMap m ON m.SourceId = s.Id
        JOIN dbo.AspNetRoles t ON t.Id = m.TargetId
        WHERE m.IsNew = 1 OR t.Name COLLATE Latin1_General_100_BIN2 <> s.Name COLLATE Latin1_General_100_BIN2)
        THROW 51000, 'Role ID collision or role name mismatch. No changes applied.', 1;

    -- Any difference on an existing role must be reviewed: changing it could affect other users.
    IF EXISTS (
        SELECT m.TargetId, c.ClaimType COLLATE Latin1_General_100_BIN2, c.ClaimValue COLLATE Latin1_General_100_BIN2
        FROM @RoleClaims c JOIN @RoleMap m ON m.SourceId = c.RoleId WHERE m.IsNew = 0
        EXCEPT
        SELECT c.RoleId, c.ClaimType COLLATE Latin1_General_100_BIN2, c.ClaimValue COLLATE Latin1_General_100_BIN2
        FROM dbo.AspNetRoleClaims c WITH (UPDLOCK, HOLDLOCK) JOIN @RoleMap m ON m.TargetId = c.RoleId WHERE m.IsNew = 0
    ) OR EXISTS (
        SELECT c.RoleId, c.ClaimType COLLATE Latin1_General_100_BIN2, c.ClaimValue COLLATE Latin1_General_100_BIN2
        FROM dbo.AspNetRoleClaims c WITH (UPDLOCK, HOLDLOCK) JOIN @RoleMap m ON m.TargetId = c.RoleId WHERE m.IsNew = 0
        EXCEPT
        SELECT m.TargetId, c.ClaimType COLLATE Latin1_General_100_BIN2, c.ClaimValue COLLATE Latin1_General_100_BIN2
        FROM @RoleClaims c JOIN @RoleMap m ON m.SourceId = c.RoleId WHERE m.IsNew = 0
    )
        THROW 51000, 'Existing production role claims differ. Resolve explicitly; shared role claims will not be changed.', 1;

    DECLARE @SourceUserId nvarchar(450) = (SELECT Id FROM @Users);
    DECLARE @TargetUserId nvarchar(450), @ExistingUser bit = 0;
    IF (SELECT COUNT(*) FROM dbo.AspNetUsers WITH (UPDLOCK, HOLDLOCK)
        WHERE NormalizedEmail = N'ADMIN@VRANJIC.LOCAL' OR NormalizedUserName = N'ADMIN@VRANJIC.LOCAL'
           OR Email = N'admin@vranjic.local' OR UserName = N'admin@vranjic.local') > 1
        THROW 51000, 'Multiple destination accounts match this email or username.', 1;
    SELECT @TargetUserId = Id FROM dbo.AspNetUsers
        WHERE NormalizedEmail = N'ADMIN@VRANJIC.LOCAL' OR NormalizedUserName = N'ADMIN@VRANJIC.LOCAL'
           OR Email = N'admin@vranjic.local' OR UserName = N'admin@vranjic.local';
    IF @TargetUserId IS NOT NULL
    BEGIN
        SET @ExistingUser = 1;
        IF NOT EXISTS (SELECT 1 FROM dbo.AspNetUsers WHERE Id = @TargetUserId
            AND NormalizedEmail = N'ADMIN@VRANJIC.LOCAL' AND NormalizedUserName = N'ADMIN@VRANJIC.LOCAL'
            AND Email = N'admin@vranjic.local' AND UserName = N'admin@vranjic.local'
            AND EmailConfirmed = 1 AND NULLIF(PasswordHash, N'') IS NOT NULL
            AND (LockoutEnabled = 0 OR LockoutEnd IS NULL OR LockoutEnd <= SYSDATETIMEOFFSET()))
            THROW 51000, 'Existing destination account differs, is unconfirmed, locked or lacks a password. Review manually.', 1;
    END
    ELSE
    BEGIN
        SET @TargetUserId = @SourceUserId;
        IF EXISTS (SELECT 1 FROM dbo.AspNetUsers WITH (UPDLOCK, HOLDLOCK) WHERE Id = @TargetUserId)
            THROW 51000, 'Source user ID belongs to another destination account.', 1;
    END;

    -- Preserve all existing claims; stop on conflicting values instead of silently broadening them.
    IF EXISTS (SELECT 1 FROM dbo.AspNetUserClaims t WITH (UPDLOCK, HOLDLOCK)
        JOIN @UserClaims s ON (s.ClaimType COLLATE Latin1_General_100_BIN2 = t.ClaimType COLLATE Latin1_General_100_BIN2
            OR (s.ClaimType IS NULL AND t.ClaimType IS NULL))
        WHERE t.UserId = @TargetUserId AND (
            s.ClaimValue COLLATE Latin1_General_100_BIN2 <> t.ClaimValue COLLATE Latin1_General_100_BIN2
            OR (s.ClaimValue IS NULL AND t.ClaimValue IS NOT NULL)
            OR (s.ClaimValue IS NOT NULL AND t.ClaimValue IS NULL)))
        THROW 51000, 'Conflicting destination user claim. Review manually.', 1;

    INSERT dbo.AspNetRoles (Id, Name, NormalizedName, ConcurrencyStamp)
        SELECT r.Id, r.Name, r.NormalizedName, CONVERT(nvarchar(36), NEWID())
        FROM @Roles r JOIN @RoleMap m ON m.SourceId = r.Id WHERE m.IsNew = 1;
    INSERT dbo.AspNetRoleClaims (RoleId, ClaimType, ClaimValue)
        SELECT m.TargetId, c.ClaimType, c.ClaimValue FROM @RoleClaims c
        JOIN @RoleMap m ON m.SourceId = c.RoleId WHERE m.IsNew = 1;
    IF @ExistingUser = 0
        INSERT dbo.AspNetUsers (Id, UserName, NormalizedUserName, Email, NormalizedEmail, EmailConfirmed,
            PasswordHash, SecurityStamp, ConcurrencyStamp, PhoneNumber, PhoneNumberConfirmed,
            TwoFactorEnabled, LockoutEnd, LockoutEnabled, AccessFailedCount)
        SELECT Id, UserName, NormalizedUserName, Email, NormalizedEmail, EmailConfirmed,
            PasswordHash, CONVERT(nvarchar(36), NEWID()), CONVERT(nvarchar(36), NEWID()), PhoneNumber,
            PhoneNumberConfirmed, TwoFactorEnabled, LockoutEnd, LockoutEnabled, AccessFailedCount FROM @Users;
    INSERT dbo.AspNetUserRoles (UserId, RoleId)
        SELECT @TargetUserId, m.TargetId FROM @RoleMap m WHERE NOT EXISTS (
            SELECT 1 FROM dbo.AspNetUserRoles WITH (UPDLOCK, HOLDLOCK)
            WHERE UserId = @TargetUserId AND RoleId = m.TargetId);
    INSERT dbo.AspNetUserClaims (UserId, ClaimType, ClaimValue)
        SELECT @TargetUserId, s.ClaimType, s.ClaimValue FROM @UserClaims s WHERE NOT EXISTS (
            SELECT 1 FROM dbo.AspNetUserClaims t WHERE t.UserId = @TargetUserId
            AND (t.ClaimType COLLATE Latin1_General_100_BIN2 = s.ClaimType COLLATE Latin1_General_100_BIN2
                OR (t.ClaimType IS NULL AND s.ClaimType IS NULL))
            AND (t.ClaimValue COLLATE Latin1_General_100_BIN2 = s.ClaimValue COLLATE Latin1_General_100_BIN2
                OR (t.ClaimValue IS NULL AND s.ClaimValue IS NULL)));

    SELECT @Apply AS WillCommit, @TargetUserId AS TargetUserId,
        @ExistingUser AS ExistingAccountAndPasswordPreserved;
    SELECT r.Name AS ResultingRole FROM dbo.AspNetUserRoles ur
        JOIN dbo.AspNetRoles r ON r.Id = ur.RoleId WHERE ur.UserId = @TargetUserId;
    IF @Apply = 1
    BEGIN
        COMMIT;
        PRINT 'COMMITTED: administrator import completed.';
    END
    ELSE
    BEGIN
        ROLLBACK;
        PRINT 'PREVIEW ONLY: all changes rolled back. Set @Apply = 1 for the committed run.';
    END;
END TRY
BEGIN CATCH
    IF @@TRANCOUNT > 0 ROLLBACK;
    THROW;
END CATCH;
